// Public types facade for the dashboard.
//
// Wire DTOs (`MemoryDto`, `GraphResponseDto`, `VestigeEvent`, …) are
// generated by ts-rs from Rust structs in `crates/vestige-mcp/src/dashboard/wire/`
// and imported here under their legacy names so existing call sites
// don't have to change. To regenerate after a backend change:
//
//   cargo test -p vestige-mcp --lib dashboard
//
// Anything below the "// === Dashboard-only types ===" marker has no
// backend counterpart — UI-only constants, color tables, helper unions,
// and types for endpoints that still pass `serde_json::Value` through
// (dream / explore / FSRS rating literals).

import type {
  ConfidenceEntryDto,
  ConfidenceResultDto,
  ConsolidationResultDto,
  CreateIntentionResponseDto,
  DecisionDto,
  DecisionListResponseDto,
  DeepRefContradictionDto,
  DeepRefEvidenceDto,
  DeepRefEvolutionDto,
  DeepReferenceResultDto,
  DeepRefInsightDto,
  DeepRefSupersededDto,
  EndangeredMemoryDto,
  ExploreResponseDto,
  ExploreResultDto,
  VestigeEvent as GeneratedVestigeEvent,
  GraphEdgeDto,
  GraphNodeDto,
  GraphResponseDto,
  HealthCheckDto,
  HubDto,
  HubListResponseDto,
  InsightDto,
  InsightListResponseDto,
  IntentionItemDto,
  IntentionListResponseDto,
  MemoryChangelogDto,
  MemoryChangelogEntryDto,
  MemoryDto,
  MemoryListResponseDto,
  MemoryStatusDto,
  MemoryUpdateResultDto,
  PredictedMemoryDto,
  PredictResponseDto,
  ReflectInsightDto,
  ReflectResultDto,
  RetentionBucketDto,
  RetentionDistributionDto,
  ReviewItemDto,
  ReviewQueueResponseDto,
  ReviewResultDto,
  SearchResultDto,
  SystemStatsDto,
  TemporalEntryDto,
  TemporalResultDto,
  TimelineDayDto,
  TimelineMemoryDto,
  TimelineResponseDto,
} from './generated';

// Re-export everything generated, in case a caller wants the raw DTO names.
export * from './generated';

// ---------------------------------------------------------------------------
// Aliases — legacy dashboard-side names mapped to the generated DTOs.
// These two-line aliases mean every call site keeps importing
// `Memory`, `SearchResult`, etc., and gets compile errors automatically
// when the wire DTO drifts.
// ---------------------------------------------------------------------------

