export type TimelineDay = TimelineDayDto;
export type TimelineMemory = TimelineMemoryDto;
export type TimelineResponse = TimelineResponseDto;
export type GraphNode = GraphNodeDto;
export type GraphEdge = GraphEdgeDto;
export type GraphResponse = GraphResponseDto;
export type RetentionDistribution = RetentionDistributionDto;
export type RetentionBucket = RetentionBucketDto;
export type EndangeredMemory = EndangeredMemoryDto;
export type ConsolidationResult = ConsolidationResultDto;
export type IntentionItem = IntentionItemDto;
export type IntentionListResponse = IntentionListResponseDto;
export type CreateIntentionResponse = CreateIntentionResponseDto;
export type ReflectResult = ReflectResultDto;
export type ReflectInsight = ReflectInsightDto;
export type TemporalEntry = TemporalEntryDto;
