// VestigeEvent: the generated discriminated union is strictly better
// (per-variant `data` types instead of `Record<string, unknown>`), so
// re-export it under the legacy name.
export type VestigeEvent = GeneratedVestigeEvent;

/**
 * The set of `type` discriminators on `VestigeEvent`. Includes the
 * synthetic `"Connected"` event the dashboard injects after the WS
 * socket opens — never sent by the backend, hence the union extension.
 */
export type VestigeEventType = VestigeEvent['type'] | 'Connected';

/**
 * `VestigeEvent` plus a stable monotonic id for React keying. The
 * client assigns `_id` at receive time — it never crosses the wire.
 */
export type IdentifiedEvent = VestigeEvent & { _id: number };

// ---------------------------------------------------------------------------
// === Dashboard-only types ===
// Things that have no DTO yet (dream still streams through `Json<Value>`,
// FSRS rating is just a literal union, intention helpers are derived from
// the DTO).
// ---------------------------------------------------------------------------

/** FSRS-6 rating values. 1=Again (forgot), 2=Hard, 3=Good, 4=Easy. */
export type FsrsRating = 1 | 2 | 3 | 4;

/** Intention trigger discriminator — sent on POST, never inspected on GET. */
export type TriggerType = 'context' | 'time' | 'event';
export type IntentionPriority = IntentionItem['priority'];
export type IntentionStatus = IntentionItem['status'];

/**
 * Temporal-versioning action discriminator. Mirrors the `action` arg
 * accepted by `tools::temporal` and the value echoed back in
 * `TemporalResultDto.action`. Kept as a literal union (not just
 * `TemporalResult["action"]: string`) because the dashboard's
 * `<TemporalPage>` switches on it exhaustively.
 */
export type TemporalAction = 'current' | 'expired' | 'history' | 'invalidate';

/**
 * Output of `tools/dream::execute`. Still hand-typed because the dream
 * engine emits a complex nested shape that hasn't been DTO-fied yet —
 * see `dashboard/handlers/cognitive.rs::trigger_dream`.
 *
 * TODO(Q-vestige-typesafety): port to `wire::dream` and replace this
 * block with `export type DreamResult = DreamResultDto`.
 */
export interface DreamResult {
  status: string;
  memoriesReplayed: number;
  wakingTagsProcessed: number;
  wakingTagsCleared: number;
  connectionsPersisted: number;
  insights: DreamInsight[];
  contradictions: ContradictionPair[];
  /**
   * Currently always empty — engine only counts demotions, not their IDs.
   * Kept on the wire so the dashboard can render the count consistently
   * with the strengthened/downscaled stats.
   */
  memoriesDemoted: string[];
  phases: DreamPhase[];
  stats: DreamStats;
}

export interface DreamPhase {
  phase: string;
  durationMs: number;
  memoriesProcessed: number;
  actions: string[];
}

export interface DreamStats {
  creativeConnectionsFound: number;
  connectionsPersisted: number;
  memoriesStrengthened: number;
  memoriesDownscaled: number;
  emotionalProcessed: number;
  contradictionsFound: number;
  insightsGenerated: number;
  durationMs: number;
}

export interface DreamInsight {
  type: string;
  insight: string;
  sourceMemories: string[];
  confidence: number;
  noveltyScore: number;
}

/**
 * A pair of memories the dream engine flagged as contradictory.
 * Symmetric — neither side is the "winner". Resolution is a UI concern.
 */
export interface ContradictionPair {
  memoryA: string;
  memoryB: string;
  confidence: number;
  insight: string;
}

/**
 * Local helper for the importance widget — derives directly from the
 * generated `ImportanceScoreDto.composite` to drive the save/skip CTA.
 * Kept here because the rule lives on the dashboard side.
 */
export type ImportanceRecommendation = 'save' | 'skip';

/**
 * UI-side projection of `ImportanceScoreDto` with a derived recommendation.
 * Use `toImportanceScore(dto)` to construct it (in `lib/importance.ts`).
 */
export interface ImportanceScore {
  composite: number;
  channels: {
    novelty: number;
    arousal: number;
    reward: number;
    attention: number;
  };
  recommendation: ImportanceRecommendation;
}

