/**
 * Three-tier retention color: green > 0.7, amber > 0.4, red below.
 * Thresholds match the FSRS-6 desired-retention defaults; if the engine
 * changes its `min_retention` policy we should bump these too.
 */
export function retentionColor(r: number): string {
  if (r > 0.7) return '#10b981';
  if (r > 0.4) return '#f59e0b';
  return '#ef4444';
}

